a<-commandArgs(TRUE);stopifnot(length(a)==1);v<-read.csv(a[1]);rows<-lapply(seq_len(nrow(v)),function(i){p<-v$Package[i];actual<-if(requireNamespace(p,quietly=TRUE))as.character(packageVersion(p))else NA_character_;data.frame(package=p,expected=v$Version[i],actual=actual,matches=identical(actual,v$Version[i]))});z<-do.call(rbind,rows);print(subset(z,!matches));if(any(!z$matches))quit(status=1)
